examples.good:
RouteRow::RouteRow()
{
    addAndMakeVisible (amount);
    addMouseListener (this, true);
}

void RouteRow::mouseExit (const juce::MouseEvent&)
{
    if (hovered && ! isMouseOver (true))
        hovered (std::nullopt);
}

